// import and run Promise polyfill first (😠 #hateIE)
import { polyfill as PromisePolyfill} from "es6-promise";
PromisePolyfill();

// Imports and registers
import {HMIWebExperionServicesActivityCreationAndData} from '@hw/experionservices/unbundled/HMIWebExperionServicesActivityCreationAndData';
import {ActivityCreationElement} from '@hw/hmiweb-activity-creation/unbundled/index';
import {ActivityDataElement} from '@hw/hmiweb-activity-data/unbundled/index';
import {HmiwebTsLogger} from "@hw/hmiweb-core/js/logging/HmiwebTsLogger";
import {HmiwebTsLocalisation} from "@hw/hmiweb-core/js/localisation/HmiwebTsLocalisation";
import {HmiwebTsLocalStorage} from "@hw/hmiweb-core/js/utils/HmiwebTsLocalStorage";

HmiwebTsLocalStorage.register(HmiwebTsLogger.instance);
let service = new HMIWebExperionServicesActivityCreationAndData();
service.register(HmiwebTsLogger.simpleInstance);
ActivityCreationElement.register(HmiwebTsLogger.instance, HmiwebTsLocalisation.instance, service.activityCreationAndDataService);
ActivityDataElement.register(HmiwebTsLogger.instance, HmiwebTsLocalisation.instance, service.activityCreationAndDataService, service.pointDataService, service.pointDataSubscriptionService);

window.addEventListener("unload", () => {
    service.dispose();
    service = null;
});
